const { chromium } = require('playwright');
const D = '/private/var/folders/hf/35wnqrnj2bbb1_llbg87zlt40000gn/T/vs-d6e27d234cc42de3';
const sizes = [['square',1080,1080],['landscape',1920,1080],['story',1080,1920]];
(async () => {
  const b = await chromium.launch();
  let fail = 0;
  for (const [name,w,h] of sizes) {
    const p = await b.newPage({ viewport:{width:w,height:h} });
    await p.goto('file://'+D+'/card.html');
    await p.evaluate(() => document.fonts.ready);
    const r = await p.evaluate(({w,h}) => {
      const out = { bad: [], circles: [], font: null, scroll: null };
      out.scroll = { sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight };
      // font actually applied?
      const t = document.querySelector('.title');
      out.font = getComputedStyle(t).fontFamily;
      const sel = '.header img,.event-name,.name,.role,.title,.meta,.btn,.portrait';
      const nodes = [...document.querySelectorAll(sel)].filter(n => getComputedStyle(n).display !== 'none');
      const boxes = [];
      for (const n of nodes) {
        const b = n.getBoundingClientRect();
        const key = n.className || n.tagName;
        boxes.push({ key, b });
        if (b.left < -0.5 || b.top < -0.5 || b.right > w + 0.5 || b.bottom > h + 0.5)
          out.bad.push(`OUT-OF-FRAME ${key} ${JSON.stringify(b.toJSON())}`);
        // text clipping: scroll size vs client size
        if (n.scrollWidth > n.clientWidth + 1 && getComputedStyle(n).overflow !== 'hidden')
          out.bad.push(`H-CLIP ${key} ${n.scrollWidth}>${n.clientWidth}`);
      }
      for (const n of document.querySelectorAll('.portrait')) {
        const b = n.getBoundingClientRect();
        if (b.width === 0) continue;
        const cs = getComputedStyle(n);
        out.circles.push({ w: b.width, h: b.height, br: cs.borderRadius, sq: Math.abs(b.width-b.height) < 0.5 });
        const img = n.querySelector('img'), ib = img.getBoundingClientRect();
        if (Math.abs(ib.width-ib.height) > 0.5) out.bad.push(`IMG-NOT-SQUARE ${ib.width}x${ib.height}`);
      }
      // pairwise overlap of text boxes
      for (let i=0;i<boxes.length;i++) for (let j=i+1;j<boxes.length;j++) {
        const a=boxes[i].b, c=boxes[j].b;
        const ox = Math.min(a.right,c.right)-Math.max(a.left,c.left);
        const oy = Math.min(a.bottom,c.bottom)-Math.max(a.top,c.top);
        if (ox > 1 && oy > 1) out.bad.push(`OVERLAP ${boxes[i].key} / ${boxes[j].key} ${ox.toFixed(0)}x${oy.toFixed(0)}`);
      }
      return out;
    }, {w,h});
    const scrollOK = r.scroll.sw <= w && r.scroll.sh <= h;
    console.log(`\n=== ${name} ${w}x${h} ===`);
    console.log(' font:', r.font, '| scroll:', JSON.stringify(r.scroll), scrollOK ? 'OK' : 'OVERFLOW');
    console.log(' circles:', JSON.stringify(r.circles));
    if (!scrollOK) { fail++; }
    if (r.bad.length) { fail++; r.bad.forEach(x => console.log('  !!', x)); } else console.log('  no defects');
    await p.close();
  }
  await b.close();
  console.log(fail ? `\nFAILURES: ${fail}` : '\nALL CHECKS PASSED');
})();
EOF
node /tmp/check.js
